for m in MODULES:
    d=f'./{m}'
    os.makedirs(d, exist_ok=True)
    eng=f'// filepath: pcc/{m}/{m}_engine.js\nmodule.exports.version=\'v3.54.54.0\';\nmodule.exports.module=\'{m}\';\nmodule.exports.functions={{}};\n'
